/*
 * Implementation
 */

enum class CaseMappingType {
  Upper = 0,
  Lower,
  Title,
};

enum class SpecialCasingContext {
  Unassigned,
  Final_Sigma,
  Not_Final_Sigma,
  After_Soft_Dotted,
  More_Above,
  Before_Dot,
  Not_Before_Dot,
  After_I,
};

struct SpecialCasing {
  const char32_t *lower;
  const char32_t *title;
  const char32_t *upper;
  const char *language;
  SpecialCasingContext context;

  const char32_t *case_mapping_codes(CaseMappingType type) const {
    switch (type) {
      case CaseMappingType::Upper:
        return upper;
      case CaseMappingType::Lower:
        return lower;
      case CaseMappingType::Title:
        return title;
    }
    // NOTREACHED
    return nullptr;
  }
};

struct CaseFolding {
  const char32_t C;
  const char32_t S;
  const char32_t *F;
  const char32_t T;
};

struct ScriptExtension {
  size_t offset;  // into _script_extension_scripts
  size_t count;
};

struct SpecialCasingGroup {
  size_t offset;  // into _special_case_mapping_context_values
  size_t count;
};

struct NormalizationProperties {
  int combining_class;
  const char *compat_format;
  const char32_t *codes;
};

